// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Random;

import org.junit.jupiter.api.Test;

class LmdbAdjacencyArenaSizingPlanTest {

	private static final long TEST_REGION_BYTES = 4096;

	@Test
	void simulatedReferencesAndCapacityExactlyMatchTheRealAllocator() {
		long[][] allocations = {
				{ 24, 8 }, { 1, 8 }, { 4000, 8 }, { 100, 16 }, { 8, 8 }, { 4096, 4096 }, { 56, 8 }, { 3000, 8 },
				{ 3000, 8 }, { 17, 8 }
		};

		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
		long[] plannedRefs = new long[allocations.length];
		for (int i = 0; i < allocations.length; i++) {
			plannedRefs[i] = plan.allocate(allocations[i][0], allocations[i][1]);
		}
		plan.seal();

		try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(plan)) {
			for (int i = 0; i < allocations.length; i++) {
				long actualRef = arena.allocateRef(allocations[i][0], allocations[i][1]);
				assertThat(actualRef).as("allocation %d", i).isEqualTo(plannedRefs[i]);
				// the reference is directly usable
				assertThat(arena.slice(actualRef, allocations[i][0]).byteSize()).isEqualTo(allocations[i][0]);
			}
			assertThat(arena.allocatedBytes()).isEqualTo(plan.allocatedBytes());
			assertThat(arena.capacityBytes()).isEqualTo(plan.capacityBytes());
		}
	}

	@Test
	void randomizedSequencesMatchAndAccountForSlack() {
		Random random = new Random(27);
		for (int round = 0; round < 20; round++) {
			LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
			int count = 1 + random.nextInt(64);
			long[][] allocations = new long[count][2];
			for (int i = 0; i < count; i++) {
				allocations[i][0] = 1 + random.nextInt((int) TEST_REGION_BYTES);
				allocations[i][1] = 1L << random.nextInt(4); // 1, 2, 4, 8 -> effective 8
				plan.allocate(allocations[i][0], allocations[i][1]);
			}
			plan.seal();

			try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(plan)) {
				LmdbAdjacencyArenaSizingPlan replay = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
				for (long[] allocation : allocations) {
					assertThat(arena.allocateRef(allocation[0], allocation[1]))
							.isEqualTo(replay.allocate(allocation[0], allocation[1]));
				}
				assertThat(arena.capacityBytes()).isEqualTo(plan.capacityBytes());
				// capacity fully decomposes into logical bytes, tracked slack, and the aligned final tail
				assertThat(plan.capacityBytes()).isGreaterThanOrEqualTo(plan.allocatedBytes() + plan.slackBytes() - 8);
			}
		}
	}

	@Test
	void lastRegionCapacityIsTheExactAlignedTail() {
		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
		plan.allocate(4000, 8); // region 0: 8..4008
		plan.allocate(100, 8); // region 1: 4096..4196
		plan.seal();

		assertThat(plan.regionCount()).isEqualTo(2);
		assertThat(plan.regionCapacity(0)).isEqualTo(TEST_REGION_BYTES);
		assertThat(plan.regionCapacity(1)).isEqualTo(104); // 100 bytes aligned up to 8
		assertThat(plan.capacityBytes()).isEqualTo(TEST_REGION_BYTES + 104);
	}

	@Test
	void divergingReplayIsRejectedInsteadOfOvercommitting() {
		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
		plan.allocate(64, 8);
		plan.seal();

		try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(plan)) {
			arena.allocateRef(64, 8);
			// one extra allocation diverges from the sealed plan
			assertThatThrownBy(() -> arena.allocateRef(64, 8)).isInstanceOf(IllegalStateException.class);
		}
	}

	@Test
	void sealedPlanRejectsFurtherSimulationAndUnsealedPlanRejectsArenaConstruction() {
		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
		plan.allocate(8, 8);

		assertThatIllegalArgumentException().isThrownBy(() -> new LmdbAdjacencyArena(plan));

		plan.seal();
		assertThatThrownBy(() -> plan.allocate(8, 8)).isInstanceOf(IllegalStateException.class);
	}

	@Test
	void emptyPlanHasNoRegions() {
		LmdbAdjacencyArenaSizingPlan plan = new LmdbAdjacencyArenaSizingPlan(TEST_REGION_BYTES);
		plan.seal();

		assertThat(plan.regionCount()).isZero();
		assertThat(plan.capacityBytes()).isZero();

		try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(plan)) {
			assertThat(arena.capacityBytes()).isZero();
		}
	}
}
